(2806058, 388695, 42100, '<td valign="top">Does give a very strong feeling of being watched, even though it''s just a statute.  Well done!</td>', 'Does give a very strong feeling of being watched, even though it''s just a statute.  Well done!', '2006-09-06 15:38:03.000000', NULL, 1),
(2806067, 390066, 30049, '<td valign="top">Clever idea.  This image feels 3D-ish.  Kind of wish the tip of the erase was also in focus, but it''s still a fun photo.  Best of luck to you in the challenge.</td>', 'Clever idea.  This image feels 3D-ish.  Kind of wish the tip of the erase was also in focus, but it''s still a fun photo.  Best of luck to you in the challenge.', '2006-09-06 15:39:51.000000', NULL, 1),
(2806098, 388745, 30049, '<td valign="top">Nice subject, well postioned in the composition.  Good lighting overall (a tad bit harsh on the guitar neck), and the image is well focused.  The diagonal lines of the bench and back wall add additional interest.  Good luck in the challenge.</td>', 'Nice subject, well postioned in the composition.  Good lighting overall (a tad bit harsh on the guitar neck), and the image is well focused.  The diagonal lines of the bench and back wall add additional interest.  Good luck in the challenge.', '2006-09-06 15:48:02.000000', NULL, 1),
(2806111, 390122, 30049, '<td valign="top">I like this image overall.  I don''t mind pet portraits, I''ve done a couple myself.  ;^)  The thing that is going to pull this shot down is the focal point.  Even your title eludes to it - the focal point is on the nose when the eyes are what should be tack sharp.  Additionally, the nose isn''t on an intersecting ROT point.  The eyes are.  This is one case of the title working against you maybe?  I like the bokeh you''ve got working in the background.  The DOF is very good, as is the lighting in general.  Best of luck to you in the challenge.</td>', 'I like this image overall.  I don''t mind pet portraits, I''ve done a couple myself.  ;^)  The thing that is going to pull this shot down is the focal point.  Even your title eludes to it - the focal point is on the nose when the eyes are what should be tack sharp.  Additionally, the nose isn''t on an intersecting ROT point.  The eyes are.  This is one case of the title working against you maybe?  I like the bokeh you''ve got working in the background.  The DOF is very good, as is the lighting in general.  Best of luck to you in the challenge.', '2006-09-06 15:53:02.000000', NULL, 1),
(2806114, 391396, 50641, '<td valign="top">yes, hang in there, and beware the <a href="//dpchallenge.com/image.php?IMAGE_ID=389825" rel="nofollow" target="_blank">assassin bug</a>...</td>', 'yes, hang in there, and beware the assassin bug...', '2006-09-06 15:54:11.000000', NULL, 1),
(2806115, 391322, 30049, '<td valign="top">Very nice use of lighting here.  Well done!</td>', 'Very nice use of lighting here.  Well done!', '2006-09-06 15:54:37.000000', NULL, 1),
(2806117, 391774, 50641, '<td valign="top">Thanks for the interesting subject.  Nice lighting and comp.</td>', 'Thanks for the interesting subject.  Nice lighting and comp.', '2006-09-06 15:56:10.000000', NULL, 1),
(2806118, 391312, 30049, '<td valign="top">This has a hard, fast, edgy feel to it - which is probably what you were going for with the B/W treatment, bit of noise, and motion blur.  It works.  ;^)  Good luck in the challenge.</td>', 'This has a hard, fast, edgy feel to it - which is probably what you were going for with the B/W treatment, bit of noise, and motion blur.  It works.  ;^)  Good luck in the challenge.', '2006-09-06 15:56:23.000000', NULL, 1),
(2806123, 391237, 50641, '<td valign="top">Wow, how''d his reflection get all the way over there??  Nice scene and composition.</td>', 'Wow, how''d his reflection get all the way over there??  Nice scene and composition.', '2006-09-06 15:57:39.000000', NULL, 1),
(2806130, 391802, 50641, '<td valign="top">As far as sky shots go, this is killer.  I like the way it addresess the thirds too.</td>', 'As far as sky shots go, this is killer.  I like the way it addresess the thirds too.', '2006-09-06 15:58:48.000000', NULL, 1),
(2806131, 391260, 50641, '<td valign="top">Terrific focus and good level of sharpness.</td>', 'Terrific focus and good level of sharpness.', '2006-09-06 15:59:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2806132, 388625, 30049, '<td valign="top">Some voters are going to have a difficult time with finding the ROT''s usage in this image as the horizon (buildings) appears near center.  I know it''s not, but it feels that way.  Another thing that may hold this back is the image lacks a clear subject IMO.  Good use of a polarizer to add some depth/drama to an otherwise featureless sky.  Good luck in the challenge.</td>', 'Some voters are going to have a difficult time with finding the ROT''s usage in this image as the horizon (buildings) appears near center.  I know it''s not, but it feels that way.  Another thing that may hold this back is the image lacks a clear subject IMO.  Good use of a polarizer to add some depth/drama to an otherwise featureless sky.  Good luck in the challenge.', '2006-09-06 15:59:23.000000', NULL, 1),
(2806135, 390626, 50641, '<td valign="top">Great shot and funny too.  I do wonder how it would look with his head on the bottom third line - with that black line kind of leading you down to it.  But that''s probably a whole ''nother picture ;-)</td>', 'Great shot and funny too.  I do wonder how it would look with his head on the bottom third line - with that black line kind of leading you down to it.  But that''s probably a whole ''nother picture ;-)', '2006-09-06 16:01:55.000000', NULL, 1),
(2806137, 389917, 30049, '<td valign="top">Great catch!  Yep, ROT is fine.  Subject is interesting.  The background is amazing.  Only minor drawback for me is the goat seems a little blurred, not quite tack sharp (focused) - some movement perhaps?  Overall, nicely done.  Best of luck to you in the challenge.</td>', 'Great catch!  Yep, ROT is fine.  Subject is interesting.  The background is amazing.  Only minor drawback for me is the goat seems a little blurred, not quite tack sharp (focused) - some movement perhaps?  Overall, nicely done.  Best of luck to you in the challenge.', '2006-09-06 16:02:41.000000', NULL, 1),
(2806140, 388587, 50641, '<td valign="top">The colors in the water make this swan shot work for me.</td>', 'The colors in the water make this swan shot work for me.', '2006-09-06 16:03:13.000000', NULL, 1),
(2806146, 390986, 30049, '<td valign="top">Nice comtemporary feel to this and a good eye to pick this shot out of a mundane (for most casual observers) setting.  How did this look in B/W?  It''s almost there already with the subject material...  Good luck in the challenge.</td>', 'Nice comtemporary feel to this and a good eye to pick this shot out of a mundane (for most casual observers) setting.  How did this look in B/W?  It''s almost there already with the subject material...  Good luck in the challenge.', '2006-09-06 16:05:27.000000', NULL, 1),
