(2816397, 391564, 52500, '<td valign="top">Awesome landscape shot.  Nice use of thirds to seperate the cotton from the hills in the background.  Great job!</td>', 'Awesome landscape shot.  Nice use of thirds to seperate the cotton from the hills in the background.  Great job!', '2006-09-08 21:41:09.000000', NULL, 1),
(2816398, 391495, 52500, '<td valign="top">What a cute little girl!  Perfect exposure...I love the texture in the hair.  Very nice!</td>', 'What a cute little girl!  Perfect exposure...I love the texture in the hair.  Very nice!', '2006-09-08 21:41:53.000000', NULL, 1),
