(2816633, 391652, 60914, '<td valign="top">a bit too soft for me</td>', 'a bit too soft for me', '2006-09-08 23:30:34.000000', NULL, 1),
(2816674, 391565, 50034, '<td valign="top">Pretty face on a sweet model.  It''s good that you used fill lighting, a reflector (I''ll guess) and I''m quite sure she''s holding the reflector, too.  The lighting on the chin &amp; the nose are <i>beginning</i> to be too bright.  IMHO you would have been better served to have the reflector higher than the face &amp; slightly to the right of the camera.  As it is...low-angle fill could cause the "dracula effect" (ala Bela Lugosi) if it was much stronger.  Just a tip from someone who always seems to learn the "hard way."</td>', 'Pretty face on a sweet model.  It''s good that you used fill lighting, a reflector (I''ll guess) and I''m quite sure she''s holding the reflector, too.  The lighting on the chin & the nose are beginning to be too bright.  IMHO you would have been better served to have the reflector higher than the face & slightly to the right of the camera.  As it is...low-angle fill could cause the "dracula effect" (ala Bela Lugosi) if it was much stronger.  Just a tip from someone who always seems to learn the "hard way."', '2006-09-08 23:49:42.000000', NULL, 1),
(2816679, 389658, 50034, '<td valign="top">"I''m board!  Let''s toss a coin!  Heads or Tails!"    Cute!    :)</td>', '"I''m board!  Let''s toss a coin!  Heads or Tails!"    Cute!    :)', '2006-09-08 23:51:54.000000', NULL, 1),
(2816720, 391238, 45672, '<td valign="top">I think this capture could use some more contrast.  It looks like a really cool spot, but the contrast isn''t hight enough.  Nice take though.</td>', 'I think this capture could use some more contrast.  It looks like a really cool spot, but the contrast isn''t hight enough.  Nice take though.', '2006-09-09 00:20:33.000000', NULL, 1),
(2816721, 391166, 64086, '<td valign="top">Cool Butterfly. Needs sharper focus.</td>', 'Cool Butterfly. Needs sharper focus.', '2006-09-09 00:20:53.000000', NULL, 1),
