(2818548, 391774, 22914, '<td valign="top">Poisonous shot!!!</td>', 'Poisonous shot!!!', '2006-09-09 20:31:42.000000', NULL, 1),
(2818570, 391390, 62671, '<td valign="top">This is really good.   The red car really pops at you.  The line of the mountain runs along with the wires the car is on, excellent.  The mountain acts as a leading line to bring your eye to the car.</td>', 'This is really good.   The red car really pops at you.  The line of the mountain runs along with the wires the car is on, excellent.  The mountain acts as a leading line to bring your eye to the car.', '2006-09-09 20:48:05.000000', NULL, 1),
(2818571, 391780, 62671, '<td valign="top">Wow! Beautiful tones and textures.</td>', 'Wow! Beautiful tones and textures.', '2006-09-09 20:48:08.000000', NULL, 1),
(2818572, 389219, 62671, '<td valign="top">Interesting.   This takes some studying to see the rule of 3rds.  But once you see it, you get it.   Here is how I see it.   The subject is the splash of water that hits the end of the concrete.  There are 2 main lines dividing the image visually and they are perfectly at the 1/3rd positions.  The horizon and the line of shadow under this first broken  piece even though it isn''t seen all the way across. I think this is one of the best examples of this challenge so far.</td>', 'Interesting.   This takes some studying to see the rule of 3rds.  But once you see it, you get it.   Here is how I see it.   The subject is the splash of water that hits the end of the concrete.  There are 2 main lines dividing the image visually and they are perfectly at the 1/3rd positions.  The horizon and the line of shadow under this first broken  piece even though it isn''t seen all the way across. I think this is one of the best examples of this challenge so far.', '2006-09-09 20:48:12.000000', NULL, 1),
(2818657, 390858, 332, '<td valign="top">It''s a good picture. You are probably getting lots of comments about the quality of the picture. I can see it is only 40kb. You should always use the full 150kb that is allowed. Love the bird above the light house. Great job.</td>', 'It''s a good picture. You are probably getting lots of comments about the quality of the picture. I can see it is only 40kb. You should always use the full 150kb that is allowed. Love the bird above the light house. Great job.', '2006-09-09 21:37:44.000000', NULL, 1),
(2818662, 391570, 332, '<td valign="top">What a great subject! Is this a small crop of a large picture? Or are you using a 2x extender? There is something a bit off. But I like it alot! Great job and good luck. Hope their mommy didn''t catch up with you :)</td>', 'What a great subject! Is this a small crop of a large picture? Or are you using a 2x extender? There is something a bit off. But I like it alot! Great job and good luck. Hope their mommy didn''t catch up with you :)', '2006-09-09 21:40:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2818670, 390995, 332, '<td valign="top">A clean crisp picture. Love the flys around the head. Good job and good luck.</td>', 'A clean crisp picture. Love the flys around the head. Good job and good luck.', '2006-09-09 21:42:00.000000', NULL, 1),
(2818704, 391374, 36914, '<td valign="top">Real nice use of thirds,</td>', 'Real nice use of thirds,', '2006-09-09 22:00:38.000000', NULL, 1),
(2818710, 390550, 3214, '<td valign="top">Super high contrast mystery, makes us wonder about him.  One of the better rule of thirds shots too.</td>', 'Super high contrast mystery, makes us wonder about him.  One of the better rule of thirds shots too.', '2006-09-09 22:01:42.000000', NULL, 1),
(2818711, 391565, 30049, '<td valign="top">This meets ROT''s just fine, and she''s a lovely gal.  Face is a bit soft.  Biggest trouble I see for you with this image is the water fountains in the back - quite distracting unfortunately.  Bet of luck in the challenge.</td>', 'This meets ROT''s just fine, and she''s a lovely gal.  Face is a bit soft.  Biggest trouble I see for you with this image is the water fountains in the back - quite distracting unfortunately.  Bet of luck in the challenge.', '2006-09-09 22:02:33.000000', NULL, 1),
(2818712, 390986, 36914, '<td valign="top">White is a little blown out, and destracting. Maybe crop the right side of the picture off a little more.</td>', 'White is a little blown out, and destracting. Maybe crop the right side of the picture off a little more.', '2006-09-09 22:02:53.000000', NULL, 1),
(2818715, 391715, 36914, '<td valign="top">The lighting make the model look paper thin.</td>', 'The lighting make the model look paper thin.', '2006-09-09 22:03:50.000000', NULL, 1),
(2818717, 391139, 30049, '<td valign="top">Cute and it fit''s the ROT ok...this is a tricky shot to take.  Her face is (actually most of the image) is underexposed, but to get the exposure correct would mean potentially lighting up the fence boards too much.  Hmmm...what to do.  Maybe some fill flash set to a large negative, like -1.7, or a reflector board below her a little to bounch some light back?  Anyway, best of luck to you in the challenge.</td>', 'Cute and it fit''s the ROT ok...this is a tricky shot to take.  Her face is (actually most of the image) is underexposed, but to get the exposure correct would mean potentially lighting up the fence boards too much.  Hmmm...what to do.  Maybe some fill flash set to a large negative, like -1.7, or a reflector board below her a little to bounch some light back?  Anyway, best of luck to you in the challenge.', '2006-09-09 22:05:00.000000', NULL, 1),
(2818719, 388924, 30049, '<td valign="top">Not really getting the connection here to the challenge, theme of using ROT.  I see one shaft, not plural, and it splits the image almost perfectly down the middle.  It''s an interesting image to look at with the contrasting materials and texture.  Anyway, best of luck to you in the challenge.</td>', 'Not really getting the connection here to the challenge, theme of using ROT.  I see one shaft, not plural, and it splits the image almost perfectly down the middle.  It''s an interesting image to look at with the contrasting materials and texture.  Anyway, best of luck to you in the challenge.', '2006-09-09 22:07:17.000000', NULL, 1),
(2818732, 390970, 11518, '<td valign="top">And we have the winner here!  Well done.</td>', 'And we have the winner here!  Well done.', '2006-09-09 22:14:08.000000', NULL, 1),
(2818764, 391022, 60281, '<td valign="top">Great title! Great pic too.</td>', 'Great title! Great pic too.', '2006-09-09 22:26:19.000000', NULL, 1),
(2818770, 391082, 60281, '<td valign="top">Wonderfully saturated colours and a fine composition. I cant make my mind up whether I like the border or not.</td>', 'Wonderfully saturated colours and a fine composition. I cant make my mind up whether I like the border or not.', '2006-09-09 22:29:57.000000', NULL, 1),
(2818799, 390789, 40359, '<td valign="top">Beautiful shot!  Looks like one from Richard Hahn.  9.</td>', 'Beautiful shot!  Looks like one from Richard Hahn.  9.', '2006-09-09 22:41:14.000000', NULL, 1),
(2818801, 391556, 52731, '<td valign="top">Lovely. Added to favorites.</td>', 'Lovely. Added to favorites.', '2006-09-09 22:42:27.000000', NULL, 1),
(2818928, 390550, 30049, '<td valign="top">Based on the post-processing I think I know who took this shot.  ;^)  Had any "doll" images recently?<br/> <br/>(Oops!  Wasn''t you.  Sorry &lt;grin&gt;)<br/> <br/>Anyway, I like the subject and the composition.  Certainly met the challenge quite well.  The tonal range is great.  Not too fond of the aggressive noise reduction however.<br/> <br/>Best of luck to you in the challenge.<br/> <br/>edit to add the Oops!  ;^)<br/><br/><i>Message edited by author 2006-09-13 08:47:50.</i></td>', 'Based on the post-processing I think I know who took this shot.  ;^)  Had any "doll" images recently? (Oops!  Wasn''t you.  Sorry <grin>) Anyway, I like the subject and the composition.  Certainly met the challenge quite well.  The tonal range is great.  Not too fond of the aggressive noise reduction however. Best of luck to you in the challenge. edit to add the Oops!  ;^)', '2006-09-09 23:40:53.000000', '2006-09-13 09:47:50.000000', 1),
(2818935, 390342, 30049, '<td valign="top">This is quite delightful!  Met the challenge very well.  Simple B/W image, with a strong composition.  Brave soul to go this way as you''re likely to hear that it''s "overexposed", "blown-out", etc...  In the FWIW column, I like it and hope it does well for you.  Good luck!</td>', 'This is quite delightful!  Met the challenge very well.  Simple B/W image, with a strong composition.  Brave soul to go this way as you''re likely to hear that it''s "overexposed", "blown-out", etc...  In the FWIW column, I like it and hope it does well for you.  Good luck!', '2006-09-09 23:43:49.000000', NULL, 1),
(2818947, 391108, 30049, '<td valign="top">This is a wonderful image.  Great tone, exposure, and composition.  There''s a story being told here, but I''m not sure what it is - wish I knew.  On the positive side it''s made me think about it, which means your image is doing it''s job of holding this viewers interest.  ;^)<br/> <br/>I get the impression that the girl is a granddaughter perhaps?  Be my luck it''s a model and no real story at all...<br/> <br/>Well done.  Good luck in the challenge.</td>', 'This is a wonderful image.  Great tone, exposure, and composition.  There''s a story being told here, but I''m not sure what it is - wish I knew.  On the positive side it''s made me think about it, which means your image is doing it''s job of holding this viewers interest.  ;^) I get the impression that the girl is a granddaughter perhaps?  Be my luck it''s a model and no real story at all... Well done.  Good luck in the challenge.', '2006-09-09 23:47:31.000000', NULL, 1),
(2819060, 391794, 40370, '<td valign="top">This would have been great on a neutral background like cement or wood planks, the model and clothing are eye-catching but the green grass distracts from the mood.</td>', 'This would have been great on a neutral background like cement or wood planks, the model and clothing are eye-catching but the green grass distracts from the mood.', '2006-09-10 00:48:43.000000', NULL, 1),
