(2832939, 390965, 40667, '<td valign="top">Wow i love this! all the detail makes the difference!! love the effect the rock bottom created, it''s amazing, nice job :)</td>', 'Wow i love this! all the detail makes the difference!! love the effect the rock bottom created, it''s amazing, nice job :)', '2006-09-13 20:51:32.000000', NULL, 0),
(2833039, 390970, 39821, '<td valign="top">Kudos and accolades Mark!  I was gonna say YeeeeeeHawwwww, but Rachel used it already.  BTW, RKT called me about your Blue Ribbon.  Great POV, beautiful sky, and I like yellow and blue.</td>', 'Kudos and accolades Mark!  I was gonna say YeeeeeeHawwwww, but Rachel used it already.  BTW, RKT called me about your Blue Ribbon.  Great POV, beautiful sky, and I like yellow and blue.', '2006-09-13 21:26:32.000000', NULL, 0),
