(2833148, 391774, 57775, '<td valign="top">Awesome photo - the texture &amp; detail is amazing!  Congrats on your first ribbon!</td>', 'Awesome photo - the texture & detail is amazing!  Congrats on your first ribbon!', '2006-09-13 21:58:36.000000', NULL, 0),
(2833170, 388219, 11854, '<td valign="top">Trading post...<br/>  Another top 20! Excellent shot. The glaring red is a bit much, but the bug makes up for it.</td>', 'Trading post...  Another top 20! Excellent shot. The glaring red is a bit much, but the bug makes up for it.', '2006-09-13 22:10:05.000000', NULL, 0),
(2833314, 391636, 30982, '<td valign="top">LOL!  I actually like this for being an overprocessed picture, but what I really like is the description.  I think you''ve subliminally convinced me that I really do need NeatImage in my repetoire.</td>', 'LOL!  I actually like this for being an overprocessed picture, but what I really like is the description.  I think you''ve subliminally convinced me that I really do need NeatImage in my repetoire.', '2006-09-13 22:46:51.000000', NULL, 0),
