(2834026, 390965, 21816, '<td valign="top">An outstanding piece of work. Well done and congrats on the ribbon! Well deserved!</td>', 'An outstanding piece of work. Well done and congrats on the ribbon! Well deserved!', '2006-09-14 03:21:55.000000', NULL, 0),
(2834049, 390385, 25355, '<td valign="top">Excellent shot with great colouring.<br/>When I see these guys in Japan, I never see them flying over open water - unless it''s a flooded rice field. ;-)</td>', 'Excellent shot with great colouring.When I see these guys in Japan, I never see them flying over open water - unless it''s a flooded rice field. ;-)', '2006-09-14 03:50:59.000000', NULL, 0),
(2834083, 390965, 10909, '<td valign="top">Really magnificent. I would vote for first place ;)</td>', 'Really magnificent. I would vote for first place ;)', '2006-09-14 04:34:30.000000', NULL, 0),
(2834206, 391774, 60341, '<td valign="top">Beautiful photo! Love the cornsnake. That must have been a difficult shot, corns can be so flighty.<br/><br/><i>Message edited by author 2006-09-14 06:15:27.</i></td>', 'Beautiful photo! Love the cornsnake. That must have been a difficult shot, corns can be so flighty.', '2006-09-14 07:15:14.000000', '2006-09-14 07:15:27.000000', 0),
(2834267, 390970, 27482, '<td valign="top">Yeah, was a bit too close to comfort between you and the 2nd place.  Anyway, congrats on the ribbon dude, alwas nice to start out with the blue, now go get the rest of them :)</td>', 'Yeah, was a bit too close to comfort between you and the 2nd place.  Anyway, congrats on the ribbon dude, alwas nice to start out with the blue, now go get the rest of them :)', '2006-09-14 08:40:14.000000', NULL, 0),
